38.         ([Description("The title or key topic for this note")] string title,
39.          [Description("The content to save")] string content) =>
40.         {
41.             notes.Add(title, content);
42.             return $"Note saved: \"{title}\"";
43.         },
44.         "save_note",
45.         "Saves a research note with a title and content for later summarization."),
46. 
47.     AIFunctionFactory.Create(
48.         () => notes.GetAll(),
49.         "get_notes",
50.         "Retrieves all saved research notes."),
51. };
52. 
53. // --- Create the agent with instructions ---
54. const string instructions = """
55.     You are a research agent. When given a topic:
56.     1. Search the web multiple times to gather diverse information about the topic.
57.     2. Save important findings as notes using the save_note tool.
58.     3. After gathering enough information (at least 3 searches), retrieve your notes
59.        and produce a well-structured summary of your findings.
60.     Be thorough but concise. Always cite the type of source (news, research, encyclopedia).
61.     """;
62. 
63. var agent = new ChatClientAgent(
64.     chatClient,
65.     instructions: instructions,
66.     name: "ResearchAgent",
67.     description: "An agent that researches topics by searching the web and taking notes.",
68.     tools: tools);
69. 
