71. Console.Write("Enter a research topic: ");
72. var topic = Console.ReadLine()?.Trim();
73. if (string.IsNullOrEmpty(topic))
74. {
75.     Console.WriteLine("No topic provided. Exiting.");
76.     return;
77. }
78. 
79. Console.WriteLine($"\n🔍 Researching \"{topic}\"...\n");
80. 
81. var runOptions = new ChatClientAgentRunOptions(new ChatOptions
82. {
83.     Temperature = 0f,
84.     MaxOutputTokens = 2048,
85. });
86. 
