90. 
91. Console.WriteLine("═══════════════════════════════════════════");
92. Console.WriteLine("📋 RESEARCH SUMMARY");
93. Console.WriteLine("═══════════════════════════════════════════");
94. Console.WriteLine(response.Text);
95. Console.WriteLine("═══════════════════════════════════════════");
96. Console.WriteLine($"\n📝 Notes taken: {notes.Count}");
97. 
