 using System.ComponentModel;
 using Microsoft.Agents.AI;
 using Microsoft.Extensions.AI;

 // --- Configuration ---
 var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
     ?? throw new InvalidOperationException(
         "Set the OPENAI_API_KEY environment variable to run this agent.");

 const string modelId = "gpt-4o-mini-2024-07-18";

 // --- Build the chat client via MEAI abstraction ---
 IChatClient chatClient = new ChatClientBuilder(
         new OpenAI.OpenAIClient(apiKey).GetChatClient(modelId).AsIChatClient())
     .Build();

 // --- Define tools ---
 var notes = new ResearchNotes();

 var tools = new AITool[]
 {
     AIFunctionFactory.Create(
         (string query) =>
         {
             // Simulated web search — replace with a real search API for production use.
             return $"[Search results for \"{query}\"]\n" +
                    $"1. Wikipedia summary: {query} is a well-documented topic with applications " +
                    "in multiple domains including technology, science, and industry.\n" +
                    $"2. Recent news: New developments in {query} were announced in 2026, " +
                    "focusing on improved efficiency and broader adoption.\n" +
                    $"3. Research paper: A 2025 study found that {query} can improve outcomes by 40% " +
                    "when applied with modern frameworks.";
         },
         "search_web",
         "Searches the web for information on a given query and returns relevant results."),

     AIFunctionFactory.Create(
         ([Description("The title or key topic for this note")] string title,
          [Description("The content to save")] string content) =>
         {
             notes.Add(title, content);
             return $"Note saved: \"{title}\"";
         },
         "save_note",
         "Saves a research note with a title and content for later summarization."),

     AIFunctionFactory.Create(
         () => notes.GetAll(),
         "get_notes",
         "Retrieves all saved research notes."),
 };

 // --- Create the agent with instructions ---
 const string instructions = """
     You are a research agent. When given a topic:
     1. Search the web multiple times to gather diverse information about the topic.
     2. Save important findings as notes using the save_note tool.
     3. After gathering enough information (at least 3 searches), retrieve your notes
        and produce a well-structured summary of your findings.
     Be thorough but concise. Always cite the type of source (news, research, encyclopedia).
     """;

 var agent = new ChatClientAgent(
     chatClient,
     instructions: instructions,
     name: "ResearchAgent",
     description: "An agent that researches topics by searching the web and taking notes.",
     tools: tools);

 // --- Run the agent ---
 Console.Write("Enter a research topic: ");
 var topic = Console.ReadLine()?.Trim();
 if (string.IsNullOrEmpty(topic))
 {
     Console.WriteLine("No topic provided. Exiting.");
     return;
 }

 Console.WriteLine($"\n🔍 Researching \"{topic}\"...\n");

 var runOptions = new ChatClientAgentRunOptions(new ChatOptions
 {
     Temperature = 0f,
     MaxOutputTokens = 2048,
 });

 var response = await agent.RunAsync(
     $"Research the following topic and provide a comprehensive summary: {topic}",
     options: runOptions);

 Console.WriteLine("═══════════════════════════════════════════");
 Console.WriteLine("📋 RESEARCH SUMMARY");
 Console.WriteLine("═══════════════════════════════════════════");
 Console.WriteLine(response.Text);
 Console.WriteLine("═══════════════════════════════════════════");
 Console.WriteLine($"\n📝 Notes taken: {notes.Count}");

 // --- Helper class for note-taking ---
 class ResearchNotes
 {
     private readonly List<(string Title, string Content)> _notes = [];

     public int Count => _notes.Count;

     public void Add(string title, string content) => _notes.Add((title, content));

     public string GetAll()
     {
         if (_notes.Count == 0)
             return "No notes saved yet.";

         return string.Join("\n\n", _notes.Select((n, i) =>
             $"--- Note {i + 1}: {n.Title} ---\n{n.Content}"));
     }
 }
